const numeroInput=document.getElementById("phone_number");function sendSMS(){const e=window.location.pathname.includes("main_en"),n=document.getElementById("amount").value,t=document.getElementById("phone_number").value.replace(/-/g,""),o=document.getElementById("details").value,a=document.getElementById("bank").value;if(!(a&&t&&n&&o)){return void alert(e?"Please complete all fields.":"Por favor completa todos los campos.")}const l={bank:a,phone_number:t,amount:n,details:o};fetch("http://localhost:3000/api/sms/create-sms",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(l)}).then((e=>e.json())).then((n=>{console.log("Server response:",n);alert(e?"Message generated successfully.":"Mensaje generado con éxito."),window.location.href=".../../checkpages/success.html"})).catch((n=>{console.error("Error:",n);alert(e?"There was an error sending the message.":"Se ha producido un error al enviar el mensaje."),window.location.href=".../../checkpages/error.html"}))}numeroInput.addEventListener("input",(function(e){let n=e.target.value.replace(/\D/g,"");n.length>4&&(n=n.slice(0,4)+"-"+n.slice(4,8)),e.target.value=n}));